// Runs once for all items on purpose. The Sheets read above it emits one item
// per history row, and without that this would fan out the whole keyword list
// once per row of history.
const cfg = $('Settings').first().json;
const keywords = String(cfg.keywords || '')
  .split(/[\n,]/)
  .map((k) => k.trim())
  .filter(Boolean);

if (!keywords.length) {
  throw new Error('Settings.keywords is empty - add at least one keyword.');
}

return keywords.slice(0, 40).map((keyword) => ({ json: { keyword: keyword } }));

// One item per keyword in, one item per keyword out. Everything downstream joins
// back on position, so nothing here may drop an item.
const cfg = $('Settings').first().json;
const brand = String(cfg.brand_domain || '')
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/.*$/, '')
  .toLowerCase();
const planned = $('One Row Per Keyword').all().map((x) => x.json);
const items = $input.all();

// Every AI Overview reference arrives as a Google redirect:
// https://www.google.com/url?sa=i&...&url=<the real one>&ved=...
// Reading href straight through makes google.com the most cited domain on every
// keyword. The publisher is in the `url` parameter and is percent-encoded.
function unwrap(u) {
  const s = String(u || '');
  const m = s.match(/[?&]url=([^&]+)/);
  if (!m) return s;
  try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
}

// No URL constructor in the Code node sandbox, so the host comes off by regex.
function host(u) {
  const m = String(u || '').match(/^https?:\/\/([^/?#]+)/);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}

// Google appends screen-reader text to every reference title, and a second
// phrase to video results. Left in, the sheet reads like a caption track.
function cleanTitle(t) {
  return String(t || '')
    .replace(/\.?\s*Opens in new tab\.?\s*$/i, '')
    .replace(/,\s*(Video,\s*)?watch on YouTube\s*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Two kinds of noise ride along inside the answer text. Source chips are
// flattened into the sentence as "... upfront. BigCommerce +1", and nested list
// items embed base64 images that run to several KB each.
function cleanSnippet(s) {
  return String(s || '')
    .replace(/data:image\/[a-z+]+;base64,[A-Za-z0-9+/=]+/g, '')
    .replace(/([.!?])\s+[A-Z][\w .&'-]{0,30}\s\+\d+\s*$/, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

// `texts` is not a list of strings. Entries of type "list" have snippet null and
// hold their content in a nested `list` array - which is usually most of the
// answer, so reading only the top level throws the bullets away.
function collect(nodes, out, depth) {
  if (!Array.isArray(nodes) || depth > 3) return out;
  for (const t of nodes) {
    if (!t || typeof t !== 'object') continue;
    const s = cleanSnippet(t.snippet);
    if (s) out.push(s);
    if (Array.isArray(t.list)) collect(t.list, out, depth + 1);
  }
  return out;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const keyword = (planned[i] && planned[i].keyword) || '';
  if (!keyword) continue;

  // The SERP API answers HTTP 200 even when the search itself failed. The real
  // status is nested one level down and the reason sits in the headers - seen
  // live as {status_code: 502, headers: {'x-brd-error-code': 'captcha'},
  // body: ''}. Read only `body` and that arrives as "empty response", which
  // sends you looking for a bug in the wrong place.
  //
  // "no overview for this keyword" and "the search never happened" also look
  // identical downstream unless they are separated here.
  const wrapper = items[i].json || {};
  const innerStatus = Number(wrapper.status_code) || 0;
  let payload = wrapper.body ?? wrapper;
  let note = '';

  if (innerStatus && innerStatus !== 200) {
    const h = wrapper.headers || {};
    note = 'Bright Data could not complete the search (' + innerStatus + ')' +
      (h['x-brd-error'] ? ': ' + h['x-brd-error'] : '') +
      (h['x-brd-error-code'] ? ' [' + h['x-brd-error-code'] + ']' : '') +
      ' - it is usually worth another run';
    payload = {};
  }

  if (!note && typeof payload === 'string') {
    if (!payload.trim()) {
      note = 'Bright Data returned an empty response - this keyword was not checked';
      payload = {};
    } else {
      try { payload = JSON.parse(payload); }
      catch (e) { note = 'the search response could not be parsed'; payload = {}; }
    }
  }
  if (!note && payload && (payload.error || payload.error_message)) {
    note = 'Bright Data said: ' + String(payload.error || payload.error_message).slice(0, 160);
    payload = {};
  }

  const organic = Array.isArray(payload.organic) ? payload.organic : [];
  const organicRank = {};
  for (const o of organic) {
    const h = host(o.link);
    if (h && !organicRank[h]) organicRank[h] = Number(o.rank) || 0;
  }

  const ov = (payload.ai_overview && typeof payload.ai_overview === 'object')
    ? payload.ai_overview
    : null;

  const citations = [];
  const seen = {};
  for (const r of (ov && Array.isArray(ov.references) ? ov.references : [])) {
    const url = unwrap(r.href);
    const domain = host(url);
    if (!domain || seen[domain]) continue;
    seen[domain] = true;
    citations.push({
      domain: domain,
      url: url,
      title: cleanTitle(r.title),
      cited_at: (Number(r.index) || 0) + 1,
      organic_rank: organicRank[domain] || 0,
      also_ranks: !!organicRank[domain],
    });
  }

  const citedDomains = citations.map((c) => c.domain);
  const rankingNotCited = organic
    .map((o) => ({ domain: host(o.link), rank: Number(o.rank) || 0, title: o.title }))
    .filter((o) => o.domain && citedDomains.indexOf(o.domain) === -1)
    .slice(0, 10);

  out.push({ json: {
    keyword: keyword,
    checked: !note,
    serp_note: note,
    has_overview: !!ov && citations.length > 0,
    overview_rank: ov ? (Number(ov.rank) || 0) : 0,
    overview_text: collect(ov ? ov.texts : [], [], 0).join(' ').slice(0, 2000),
    citations: citations,
    cited_count: citations.length,
    also_ranking: citations.filter((c) => c.also_ranks).length,
    cited_not_ranking: citations.filter((c) => !c.also_ranks).map((c) => c.domain),
    ranking_not_cited: rankingNotCited,
    organic_seen: organic.length,
    brand_cited: brand ? citedDomains.indexOf(brand) !== -1 : false,
    brand_organic_rank: brand ? (organicRank[brand] || 0) : 0,
    brand_domain: brand,
  } });
}

return out;

// Reads the previous run out of the sheet and turns this run into something
// with a direction. Runs once for all items because the leaderboard and the
// comparison are both cross-keyword.
const rows = $input.all().map((x) => x.json).filter((r) => r.keyword);

// The history sheet holds every run, so "last time" means the most recent date
// present, not every row in the file. Comparing against all of history would
// mark a citation as held forever after it had been seen once.
const history = $('Read Last Run').all().map((x) => x.json).filter((h) => h && h.keyword);
let lastDate = '';
for (const h of history) {
  const d = String(h.checked_on || '');
  if (d && d > lastDate) lastDate = d;
}
const previous = {};
for (const h of history) {
  if (String(h.checked_on || '') !== lastDate) continue;
  // A row logged as `lost` records a domain that had already gone. Treating it
  // as present last week would report the same domain as lost again every run.
  if (String(h.status || '') === 'lost') continue;
  const domain = String(h.cited_domain || '').toLowerCase();
  if (!domain) continue;
  previous[String(h.keyword) + '\t' + domain] = true;
}

const withOverview = rows.filter((r) => r.has_overview);
const failed = rows.filter((r) => !r.checked);

// Share of voice across the keyword set. A domain quoted on four of six
// keywords is a different problem from one quoted on a single long tail.
const tally = {};
for (const r of withOverview) {
  for (const c of r.citations) {
    const t = tally[c.domain] || (tally[c.domain] = { domain: c.domain, keywords: 0, ranks: 0 });
    t.keywords += 1;
    if (c.also_ranks) t.ranks += 1;
  }
}
const leaderboard = Object.keys(tally)
  .map((d) => tally[d])
  .sort((a, b) => b.keywords - a.keywords || a.domain.localeCompare(b.domain))
  .slice(0, 15);

const out = [];
for (const r of rows) {
  const gained = [];
  const held = [];
  for (const c of r.citations) {
    if (lastDate && previous[r.keyword + '\t' + c.domain]) held.push(c.domain);
    else gained.push(c.domain);
  }

  // Gains and losses only mean something once there is a run to compare
  // against. On the very first run every domain would otherwise be reported as
  // new, which reads like a week of dramatic movement.
  const nowSet = r.citations.map((c) => c.domain);
  const lost = [];
  if (lastDate) {
    for (const key of Object.keys(previous)) {
      const parts = key.split('\t');
      if (parts[0] !== r.keyword) continue;
      if (nowSet.indexOf(parts[1]) === -1) lost.push(parts[1]);
    }
  }

  out.push({ json: {
    ...r,
    first_run: !lastDate,
    compared_with: lastDate || '',
    gained: lastDate ? gained : [],
    held: held,
    lost: lost,
    leaderboard: leaderboard,
    keywords_checked: rows.length,
    overviews_found: withOverview.length,
    searches_failed: failed.length,
    brand_keywords_cited: rows.filter((x) => x.brand_cited).length,
  } });
}

// A filtering step that can empty the branch takes every node below it with it,
// so a run where nothing came back still emits one item and reaches the quiet
// branch through the IF rather than by disappearing.
if (!out.length) {
  return [{ json: { nothing_checked: true, keywords_checked: 0, has_overview: false } }];
}
return out;

// One item per page to fetch: the top cited page for each keyword that produced
// an overview, capped, and deduplicated by URL because the same guide is often
// quoted on several keywords in one set.
const cfg = $('Settings').first().json;
const maxPages = Math.max(1, Number(cfg.max_pages_to_read) || 3);
const rows = $input.all().map((x) => x.json).filter((r) => r.has_overview);

// Keywords where you are not quoted come first. A keyword you already own has
// less to teach you than one you do not, and the budget is small.
rows.sort((a, b) =>
  (a.brand_cited ? 1 : 0) - (b.brand_cited ? 1 : 0) || b.cited_count - a.cited_count);

const out = [];
const seen = {};
for (const r of rows) {
  const pick = r.citations.find((c) => c.domain !== r.brand_domain) || r.citations[0];
  if (!pick || !pick.url || seen[pick.url]) continue;
  seen[pick.url] = true;
  out.push({ json: {
    keyword: r.keyword,
    read_url: pick.url,
    read_domain: pick.domain,
    read_title: pick.title,
    cited_at: pick.cited_at,
    also_ranks: pick.also_ranks,
  } });
  if (out.length >= maxPages) break;
}

// Non-empty by construction: the IF above only lets this branch run when at
// least one keyword produced an overview, and has_overview is only true when
// that overview carried at least one reference.
return out;

// The Web Unlocker returns markdown as plain text, so nothing about which URL
// produced it survives into the item. It emits one item per input in the same
// order and continues on error rather than dropping the item, so the join back
// to the plan is positional.
const plan = $('Plan Page Reads').all().map((x) => x.json);
const rows = $('Rank The Cited Domains').all().map((x) => x.json).filter((r) => r.keyword);
const items = $input.all();

// Headings are the comparison. What a quoted page has in common with the other
// quoted pages is its structure, and sending three full articles costs more and
// answers worse.
function outline(raw) {
  const body = String(raw || '');
  if (!body) return null;
  const headings = [];
  const re = /^#{2,3}\s+(.+)$/gm;
  let m;
  while ((m = re.exec(body)) !== null && headings.length < 20) {
    const h = m[1].replace(/[*_`\[\]]/g, '').trim();
    if (h && h.length < 120) headings.push(h);
  }
  const paragraphs = body
    .split('\n')
    .map((s) => s.trim())
    .filter((s) => s.length > 40 && !s.startsWith('#') && !s.startsWith('!') && !s.startsWith('|'));
  return {
    headings: headings,
    opening: paragraphs.slice(0, 2).join(' ').slice(0, 500),
    words: body.split(/\s+/).filter(Boolean).length,
    has_table: /^\|.+\|$/m.test(body),
    has_list: /^\s*[-*]\s+/m.test(body),
    has_faq: /^#{2,3}\s+.*\?\s*$/m.test(body),
  };
}

const pages = [];
for (let i = 0; i < items.length; i++) {
  const step = plan[i];
  if (!step) continue;
  const j = items[i].json || {};
  const read = (j.error || j.error_message) ? null : outline(j.data ?? j.body ?? '');
  pages.push({
    keyword: step.keyword,
    url: step.read_url,
    domain: step.read_domain,
    title: step.read_title,
    cited_at: step.cited_at,
    also_ranks: step.also_ranks,
    readable: !!read,
    headings: read ? read.headings : [],
    opening: read ? read.opening : '',
    words: read ? read.words : 0,
    has_table: read ? read.has_table : false,
    has_list: read ? read.has_list : false,
    has_faq: read ? read.has_faq : false,
  });
}

// Collapsed to a single item so the model runs once for the whole picture
// rather than once per keyword. The per-keyword rows are still read by name
// further down, so nothing is lost by narrowing here.
const first = rows[0] || {};
return [{ json: {
  brand_domain: first.brand_domain || '',
  keywords_checked: first.keywords_checked || rows.length,
  overviews_found: first.overviews_found || 0,
  brand_keywords_cited: first.brand_keywords_cited || 0,
  leaderboard: first.leaderboard || [],
  pages: pages,
  pages_read: pages.filter((p) => p.readable).length,
  keywords: rows.map((r) => ({
    keyword: r.keyword,
    has_overview: r.has_overview,
    brand_cited: r.brand_cited,
    brand_organic_rank: r.brand_organic_rank,
    cited: (r.citations || []).map((c) => c.domain),
    cited_not_ranking: r.cited_not_ranking || [],
    gained: r.gained || [],
    lost: r.lost || [],
  })),
} }];

// One row per keyword and cited domain, which is the grain the next run needs
// to tell a citation it already had from one it has just won. A keyword with no
// overview still gets a row - a blank line reads as "nothing happened here",
// and "Google answered this without quoting anyone" is a finding.
const rows = $('Rank The Cited Domains').all().map((x) => x.json).filter((r) => r.keyword);
const stamp = new Date().toISOString().slice(0, 10);

const out = [];
for (const r of rows) {
  if (!r.checked) {
    out.push({
      checked_on: stamp,
      keyword: r.keyword,
      has_overview: 'not checked',
      overview_rank: '',
      cited_domain: '',
      cited_url: '',
      cited_title: r.serp_note,
      cited_at: '',
      organic_rank: '',
      also_ranks: '',
      status: 'search failed',
      brand_cited: '',
    });
    continue;
  }
  if (!r.has_overview) {
    out.push({
      checked_on: stamp,
      keyword: r.keyword,
      has_overview: 'no',
      overview_rank: '',
      cited_domain: '',
      cited_url: '',
      cited_title: '',
      cited_at: '',
      organic_rank: r.brand_organic_rank || '',
      also_ranks: '',
      status: 'no overview',
      brand_cited: 'no',
    });
    // The overview vanishing is not the same as never having had one. Domains
    // that were quoted last run still get their own rows here, or a keyword
    // that lost its whole answer box reads identically to one that never had
    // an answer box at all.
    for (const d of r.lost) {
      out.push({
        checked_on: stamp,
        keyword: r.keyword,
        has_overview: 'no',
        overview_rank: '',
        cited_domain: d,
        cited_url: '',
        cited_title: '',
        cited_at: '',
        organic_rank: '',
        also_ranks: '',
        status: 'lost',
        brand_cited: 'no',
      });
    }
    continue;
  }
  for (const c of r.citations) {
    out.push({
      checked_on: stamp,
      keyword: r.keyword,
      has_overview: 'yes',
      overview_rank: r.overview_rank || '',
      cited_domain: c.domain,
      cited_url: c.url,
      cited_title: c.title,
      cited_at: c.cited_at,
      organic_rank: c.organic_rank || '',
      also_ranks: c.also_ranks ? 'yes' : 'no',
      status: r.first_run ? 'baseline' : (r.gained.indexOf(c.domain) !== -1 ? 'new' : 'held'),
      brand_cited: r.brand_cited ? 'yes' : 'no',
    });
  }
  // A domain that stopped being quoted has no citation row to hang off, so it
  // needs one of its own or the drop never reaches the sheet.
  for (const d of r.lost) {
    out.push({
      checked_on: stamp,
      keyword: r.keyword,
      has_overview: 'yes',
      overview_rank: r.overview_rank || '',
      cited_domain: d,
      cited_url: '',
      cited_title: '',
      cited_at: '',
      organic_rank: '',
      also_ranks: '',
      status: 'lost',
      brand_cited: r.brand_cited ? 'yes' : 'no',
    });
  }
}

if (!out.length) {
  return [{ json: { nothing_checked: true } }];
}
return out.map((r) => ({ json: r }));

// Reads the report by name rather than from this node's input, because the
// Sheets append in between returns its own confirmation shape.
// On a run where no keyword produced an overview the page reads and the model
// never execute, and reaching into a node that did not run throws. Both are
// optional to this message, so both are read defensively.
function optional(nodeName) {
  try { return $(nodeName).first().json || {}; } catch (e) { return {}; }
}

const rows = $('Build Citation Report').all().map((x) => x.json).filter((r) => r.keyword);
const ranked = $('Rank The Cited Domains').all().map((x) => x.json).filter((r) => r.keyword);
const summary = optional('Outline Cited Pages');
const brief = String(optional('Explain What Gets Cited').text || '').trim();
const cfg = $('Settings').first().json;
const brand = summary.brand_domain || (ranked[0] || {}).brand_domain || '';

if (!rows.length) {
  return [{ json: { message: 'AI Overview check ran and returned nothing to report.' } }];
}

// Every count here is user-driven, so "1 keywords" is reachable on any small
// set. Pluralise the counts rather than only the ones that happened to be
// noticed.
const plural = (n, word) => n + ' ' + word + (Number(n) === 1 ? '' : 's');
const fallback = ranked[0] || {};
const checked = Number(summary.keywords_checked || fallback.keywords_checked || 0);
const found = Number(summary.overviews_found || fallback.overviews_found || 0);
const mine = Number(summary.brand_keywords_cited || fallback.brand_keywords_cited || 0);

const lines = [
  '*AI Overview citations* - ' + plural(checked, 'keyword') + ' checked, an overview on ' +
    found + ', quoting ' + (brand || 'your domain') + ' on ' + mine,
  '',
];

const order = [];
const byKeyword = {};
for (const r of rows) {
  if (!byKeyword[r.keyword]) { byKeyword[r.keyword] = []; order.push(r.keyword); }
  byKeyword[r.keyword].push(r);
}

for (const keyword of order) {
  const set = byKeyword[keyword];
  const head = set[0];
  if (head.status === 'search failed') {
    lines.push('*' + keyword + '*  not checked - ' + head.cited_title);
    lines.push('');
    continue;
  }
  if (head.status === 'no overview') {
    const dropped = set.filter((r) => r.status === 'lost').map((r) => r.cited_domain);
    lines.push('*' + keyword + '*  no AI Overview' +
      (head.organic_rank ? ' - you rank ' + head.organic_rank + ' organically' : ''));
    if (dropped.length) lines.push('   The answer box has gone. Last run it quoted: ' + dropped.join(', '));
    lines.push('');
    continue;
  }
  const cited = set.filter((r) => r.status !== 'lost');
  const gained = set.filter((r) => r.status === 'new').map((r) => r.cited_domain);
  const lost = set.filter((r) => r.status === 'lost').map((r) => r.cited_domain);
  const quoted = head.brand_cited === 'yes';
  lines.push('*' + keyword + '*  ' + plural(cited.length, 'source') + ' quoted' +
    (quoted ? ' - including you' : (brand ? ' - not you' : '')));
  // Slack lines get unreadable past six domains, but a list that stops at six
  // while the count above it says nine reads as a contradiction, so the
  // remainder is named as a remainder rather than dropped.
  const shown = cited.slice(0, 6);
  lines.push('   ' + shown.map((r) =>
    r.cited_domain + (r.also_ranks === 'yes' ? ' (ranks ' + r.organic_rank + ')' : ' (not ranking)')
  ).join(', ') + (cited.length > shown.length
    ? ' and ' + (cited.length - shown.length) + ' more, all in the sheet'
    : ''));
  if (gained.length) lines.push('   New: ' + gained.join(', '));
  if (lost.length) lines.push('   Gone: ' + lost.join(', '));
  lines.push('');
}

const board = (summary.leaderboard || fallback.leaderboard || []).slice(0, 5);
if (board.length) {
  lines.push('*Most quoted across the set*');
  for (const d of board) {
    lines.push('   ' + d.domain + ' - ' + plural(d.keywords, 'keyword') + ', ' + d.ranks + ' also ranking');
  }
  lines.push('');
}

if (brief) {
  lines.push(brief);
  lines.push('');
}

lines.push('Every run is kept in the sheet, so read the trend rather than one week. Country: ' + cfg.country + '.');

return [{ json: { message: lines.join('\n') } }];

// Optional. Splice between 'Build Citation Report' and 'Log Citations To Sheet'
// when you only want your own visibility rather than the whole answer box.
// Keeps your rows plus the keywords where nobody was quoted, so the sheet still
// records the weeks you were absent instead of skipping them.
const brand = String($('Settings').first().json.brand_domain || '').toLowerCase();
const out = [];
for (const item of items) {
  const j = item.json || {};
  const domain = String(j.cited_domain || '').toLowerCase();
  if (!domain || (brand && domain.indexOf(brand) !== -1)) out.push({ json: j });
}
// A filter that can empty the branch takes every node below it with it, so a
// week where you were not quoted at all still emits one row.
if (!out.length) {
  return [{ json: { checked_on: '', keyword: '', status: 'not quoted this run' } }];
}
return out;
